function o(t,n="₹"){return t==null||isNaN(t)?`${n} 0.00`:`${n} ${Number(t).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})}`}function u(t){return t?new Date(t).toLocaleDateString("en-IN",{year:"numeric",month:"short",day:"numeric"}):""}function f(t){if(!t)return"";const n=new Intl.RelativeTimeFormat("en",{numeric:"auto"}),r=new Date(t)-new Date,e=Math.round(r/(1e3*60*60*24)),a=Math.round(r/(1e3*60*60)),i=Math.round(r/(1e3*60));return Math.abs(e)>0?n.format(e,"day"):Math.abs(a)>0?n.format(a,"hour"):Math.abs(i)>0?n.format(i,"minute"):"just now"}export{o as a,u as b,f};
